UPDATE documentos SET datos = '{"titulo":"FeiraLab","descricion":"A Feira da Sostibilidade como laboratorio: investigación, acción e cidadanía crítica para avanzar fronte aos retos ecosociais.","nai":"","imaxe":"f-stand-alumnas","seccions":[{"id":"s16j9nd","tipo":"heroe","oculta":false,"fondo":"claro","etiqueta":"FeiraLab · Xeración Eco-Étika","titulo":"Máis ca unha feira.","destaque":"Un laboratorio permanente.","texto":"A Feira é o momento no que meses de investigación, acción e construción colectiva de cidadanía crítica se fan visibles para toda a comunidade. Detrás hai un laboratorio de innovación educativa que traballa durante todo o curso.","imaxe":"f-stand-alumnas","imaxeAlt":"Alumnas explicando o seu stand na Feira"},{"id":"fl-laboratorio","tipo":"tarxetas","oculta":false,"fondo":"claro","etiqueta":"A Feira como laboratorio","titulo":"Cada curso, unha pregunta de investigación.","texto":"A Feira e todo o que leva ata ela sérvennos tamén para estudar, coa Universidade de Vigo, como avanzar fronte aos retos ecosociais.","columnas":2,"items":[{"etiqueta":"2025 – 2026 · Feito","titulo":"Consumo de alimentos e clima","texto":"Que comemos nos fogares de Pontevedra e que pegada climática deixa? O alumnado do IES Luís Seoane fixo enquisas por todo o concello, coa Universidade de Vigo e CIDEL Galicia, e presentou os resultados no I Foro de Desenvolvemento Local."},{"etiqueta":"2026 – 2027 · SENDA 2030 · En marcha","titulo":"Ciencia cidadá e cidadanía global","texto":"Pode a ciencia cidadá axudar a educar para unha cidadanía global? Estudámolo durante todo o curso, con cuestionarios ao alumnado ao comezo e ao final e valoracións do profesorado. O resultado será un informe aberto con recomendacións para os centros."}]},{"id":"s17o6tx","tipo":"tarxetas","oculta":false,"fondo":"verde","etiqueta":"Como traballamos","titulo":"Tres metodoloxías que se retroalimentan.","columnas":3,"items":[{"etiqueta":"ABP · Aprendizaxe Baseada en Proxectos","titulo":"Investigar para comprender","texto":"O alumnado deseña e executa proxectos de investigación interdisciplinar sobre retos da Axenda 2030, conectando saberes científicos, sociais e artísticos."},{"etiqueta":"ApS · Aprendizaxe Servizo · CIDEL Galicia","titulo":"Actuar para transformar","texto":"O eixo que une aprendizaxe e acción comunitaria: o alumnado pon o seu coñecemento ao servizo da comunidade, con rede internacional con colectivos de Galicia e América Latina."},{"etiqueta":"CC · Ciencia cidadá · Post-Growth Innovation Lab","titulo":"Investigar con rigor e impacto real","texto":"Co acompañamento científico da Universidade de Vigo, o alumnado convértese en investigador activo e conecta o local —o barrio de Monte Porreiro— co global."}]},{"id":"s18ftlu","tipo":"tarxetas","oculta":false,"fondo":"branco","etiqueta":"Liñas de traballo","titulo":"Proxectos que moven o mundo.","texto":"O alumnado investiga en liñas temáticas conectadas cos ODS que se desenvolven ao longo do curso e culminan na Feira.","columnas":3,"items":[{"etiqueta":"ODS 7 · ODS 13","titulo":"Clima, enerxía e transición ecolóxica","texto":"Cambio climático, consumo enerxético e transición xusta: datos reais, alternativas e comunicación á comunidade."},{"etiqueta":"ODS 12","titulo":"Consumo responsable e moda sostible","texto":"O impacto da fast fashion e do consumismo, xogos educativos como Naturpoly e obradoiros de economía circular."},{"etiqueta":"ODS 10 · ODS 16","titulo":"Xustiza global e cooperación internacional","texto":"Dereitos humanos, desigualdade e solidariedade internacional, en colaboración con Oxfam Intermón e SIG Comercio Xusto."},{"etiqueta":"ODS 5","titulo":"Igualdade de xénero e diversidade","texto":"Investigación e acción sobre fendas de xénero, diversidade e inclusión, co proxecto NeoFem e o Comité UNESCO do centro."},{"etiqueta":"ODS 11","titulo":"Territorio, barrio e identidade local","texto":"Monte Porreiro como laboratorio social: mapeo comunitario e axendas políticas locais."},{"etiqueta":"ODS 2 · ODS 3","titulo":"Saúde, benestar e alimentación sostible","texto":"Alimentación ecolóxica, hortas escolares, saúde mental e benestar, con entidades como Casa Grande de Xanceda e Feitoria Verde."}]},{"id":"s19fgoj","tipo":"cronoloxia","oculta":false,"fondo":"escuro","etiqueta":"Recoñecementos","titulo":"Premios autonómicos de innovación educativa.","fitos":[{"data":"2022 · 2023","titulo":"Premio Galicons-net de Innovación Educativa en Consumo Responsable (Xunta de Galicia)","estado":"feito"},{"data":"2024","titulo":"III Premio Galego de Educación para o Desenvolvemento e a Cidadanía Global, á experiencia de Eco-Étika e o IES Luís Seoane","estado":"feito"}]},{"id":"s1a42qn","tipo":"subpaxinas","oculta":false,"fondo":"claro","etiqueta":"No laboratorio","titulo":"Máis sobre FeiraLab.","nai":"feiralab"},{"id":"s1bgiks","tipo":"chamada","oculta":false,"fondo":"morado","titulo":"Queres traer o laboratorio ao teu centro?","texto":"Escríbenos e contamos como participar na próxima Feira.","botons":[{"texto":"Participa","url":"/participa/","estilo":"principal"}]}]}', actualizado = datetime('now') WHERE coleccion = 'paxinas_libres' AND id = 'feiralab';
